  # Authorization helpers read from the ACTIVE role (the role
  # currently switched into via RP-W3) rather than the persisted
  # user.role column. Without this, switching to a stu UserRole
  # would leave the actor with admin-tier `require_admin` access
  # because the persisted role column never changes. See
  # spec 01 §6 + RP-W3 for the contract.
  sig { returns(T.nilable(User)) }
  def current_student
    current_user if current_active_role == :stu
  end

  sig { returns(T.nilable(User)) }
  def current_staff
    current_user if %i[men dex sup con].include?(current_active_role)
  end

  sig { params(user: User).void }
  def sign_in(user)
    raise ArgumentError, "System accounts cannot sign in" if user.is_system?

    reset_session
    session[:user_id] = user.id
    user.touch_login! if user.respond_to?(:touch_login!)
    @current_user = user
    @current_user_loaded = true
  end

  sig { void }
  def sign_out
    reset_session
    @current_user = nil
    @current_user_loaded = true
  end

  sig { void }
